#!/usr/bin/env python3
"""Nike NKE Stock Performance Report Generator"""

import pandas as pd
import numpy as np
import json
import base64
import io
from datetime import datetime
import warnings
warnings.filterwarnings('ignore')

# ── Load Data ──────────────────────────────────────────────────────────────────
df = pd.read_csv('/app/benchmark/data.csv')
df['Date'] = pd.to_datetime(df['Date'], format='%m/%d/%Y')
df = df.sort_values('Date').reset_index(drop=True)
df.set_index('Date', inplace=True)

# ── Derived Metrics ────────────────────────────────────────────────────────────
df['DailyReturn'] = df['Close'].pct_change()
df['DailyRange'] = df['High'] - df['Low']
df['CumReturn'] = (1 + df['DailyReturn']).cumprod()

# Rolling 30-day volatility (annualized)
df['RollingVol30'] = df['DailyReturn'].rolling(30).std() * np.sqrt(252) * 100

# Drawdown
rolling_max = df['Close'].cummax()
df['Drawdown'] = (df['Close'] - rolling_max) / rolling_max * 100

# ── KPIs ───────────────────────────────────────────────────────────────────────
first_close = df['Close'].iloc[0]
last_close = df['Close'].iloc[-1]
first_date = df.index[0]
last_date = df.index[-1]
years = (last_date - first_date).days / 365.25

cumulative_return = (last_close / first_close - 1) * 100
cagr = ((last_close / first_close) ** (1 / years) - 1) * 100
max_drawdown = df['Drawdown'].min()
ann_volatility = df['DailyReturn'].std() * np.sqrt(252) * 100
avg_volume = df['Volume'].mean()

# All-time high / low
ath = df['Close'].max()
ath_date = df['Close'].idxmax()
atl = df['Close'].min()
atl_date = df['Close'].idxmin()

print(f"Period: {first_date.date()} to {last_date.date()} ({years:.1f} years)")
print(f"First close: ${first_close:.2f}, Last close: ${last_close:.2f}")
print(f"Cumulative Return: {cumulative_return:.1f}%")
print(f"CAGR: {cagr:.2f}%")
print(f"Max Drawdown: {max_drawdown:.1f}%")
print(f"Ann. Volatility: {ann_volatility:.1f}%")
print(f"Avg Daily Volume: {avg_volume/1e6:.1f}M shares")
print(f"ATH: ${ath:.2f} on {ath_date.date()}")
print(f"ATL: ${atl:.2f} on {atl_date.date()}")

# ── Annual Performance ─────────────────────────────────────────────────────────
annual = df['Close'].resample('YE').last()
annual_returns = annual.pct_change() * 100
annual_returns.index = annual_returns.index.year

# First year manually
first_year_close = df.loc[df.index.year == 2000, 'Close'].iloc[-1]
annual_returns[2000] = (first_year_close / first_close - 1) * 100
annual_returns = annual_returns.sort_index()

annual_vol = df['DailyReturn'].groupby(df.index.year).std() * np.sqrt(252) * 100
annual_vol_volume = df['Volume'].groupby(df.index.year).mean() / 1e6

print("\nAnnual Returns:")
for yr, ret in annual_returns.items():
    if not np.isnan(ret):
        print(f"  {yr}: {ret:+.1f}%")

# ── Monthly aggregations for charts ───────────────────────────────────────────
monthly_close = df['Close'].resample('ME').last()
monthly_vol = df['Volume'].resample('ME').mean() / 1e6

# ── Matplotlib charts → base64 PNG ────────────────────────────────────────────
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
import matplotlib.dates as mdates
from matplotlib.patches import FancyBboxPatch
import matplotlib.ticker as mticker

COLORS = {
    'primary': '#1B3A6B',
    'accent': '#E8572A',
    'green': '#2E7D32',
    'red': '#C62828',
    'light_blue': '#5B8DB8',
    'gold': '#F5A623',
    'bg': '#F8F9FA',
    'grid': '#E0E0E0',
    'text': '#1A1A2E',
}

plt.rcParams.update({
    'font.family': 'DejaVu Sans',
    'axes.facecolor': '#FAFAFA',
    'figure.facecolor': 'white',
    'axes.spines.top': False,
    'axes.spines.right': False,
    'axes.spines.left': True,
    'axes.spines.bottom': True,
    'axes.grid': True,
    'grid.color': COLORS['grid'],
    'grid.linewidth': 0.6,
    'grid.alpha': 0.8,
    'text.color': COLORS['text'],
    'axes.labelcolor': COLORS['text'],
    'xtick.color': COLORS['text'],
    'ytick.color': COLORS['text'],
})

def fig_to_b64(fig):
    buf = io.BytesIO()
    fig.savefig(buf, format='png', dpi=150, bbox_inches='tight',
                facecolor='white', edgecolor='none')
    buf.seek(0)
    b64 = base64.b64encode(buf.read()).decode()
    plt.close(fig)
    return b64


# Chart 1: Long-Term Price Trend (full period with annotations)
fig, ax = plt.subplots(figsize=(14, 6))
ax.fill_between(monthly_close.index, monthly_close.values, alpha=0.12, color=COLORS['primary'])
ax.plot(monthly_close.index, monthly_close.values, color=COLORS['primary'], linewidth=1.8, zorder=5)

# Key event annotations
events = [
    ('2000-09-01', 'Post-dot-com\npeak', 0, 25),
    ('2003-03-01', 'Post-crash\nrecovery', -5, -30),
    ('2008-11-01', 'GFC\ntrough', 8, 30),
    ('2012-06-01', 'Bull run\nbegins', -10, -35),
    ('2020-03-01', 'COVID\ncrash', -5, 30),
    ('2021-11-01', 'Post-COVID\nATH zone', 10, -30),
]
for ev_date, label, xoff, yoff in events:
    try:
        ev_dt = pd.Timestamp(ev_date)
        idx = monthly_close.index.get_indexer([ev_dt], method='nearest')[0]
        ev_price = monthly_close.iloc[idx]
        ax.annotate(label, xy=(monthly_close.index[idx], ev_price),
                    xytext=(xoff, yoff), textcoords='offset points',
                    fontsize=7.5, color=COLORS['accent'],
                    arrowprops=dict(arrowstyle='->', color=COLORS['accent'], lw=0.8),
                    bbox=dict(boxstyle='round,pad=0.2', facecolor='white', alpha=0.85, edgecolor=COLORS['accent'], linewidth=0.5))
    except Exception:
        pass

# Shade recessions / major downturns
for start, end, label in [
    ('2000-03', '2003-03', 'Dot-com\nbust'),
    ('2007-10', '2009-03', 'GFC'),
    ('2020-02', '2020-04', 'COVID'),
]:
    ax.axvspan(pd.Timestamp(start), pd.Timestamp(end), alpha=0.07, color=COLORS['red'], zorder=1)

ax.set_title('Nike (NKE) Closing Price — 2000 to 2026', fontsize=14, fontweight='bold',
             color=COLORS['primary'], pad=14)
ax.set_ylabel('Adjusted Close Price (USD)', fontsize=10)
ax.yaxis.set_major_formatter(mticker.FuncFormatter(lambda x, _: f'${x:.0f}'))
ax.xaxis.set_major_formatter(mdates.DateFormatter('%Y'))
ax.xaxis.set_major_locator(mdates.YearLocator(2))
plt.setp(ax.xaxis.get_majorticklabels(), rotation=45, ha='right', fontsize=8)
fig.tight_layout()
chart_price = fig_to_b64(fig)
print("Chart 1 (price trend) done.")


# Chart 2: Drawdown chart
fig, ax = plt.subplots(figsize=(14, 4))
ax.fill_between(df.index, df['Drawdown'], 0, color=COLORS['red'], alpha=0.5)
ax.plot(df.index, df['Drawdown'], color=COLORS['red'], linewidth=0.8)
ax.set_title('Peak-to-Trough Drawdown (%) — 2000–2026', fontsize=13, fontweight='bold',
             color=COLORS['primary'], pad=12)
ax.set_ylabel('Drawdown (%)', fontsize=10)
ax.yaxis.set_major_formatter(mticker.FuncFormatter(lambda x, _: f'{x:.0f}%'))
ax.xaxis.set_major_formatter(mdates.DateFormatter('%Y'))
ax.xaxis.set_major_locator(mdates.YearLocator(2))
plt.setp(ax.xaxis.get_majorticklabels(), rotation=45, ha='right', fontsize=8)

# Label max drawdown
ax.annotate(f'Max Drawdown\n{max_drawdown:.1f}%',
            xy=(df['Drawdown'].idxmin(), max_drawdown),
            xytext=(30, 15), textcoords='offset points',
            fontsize=8.5, color=COLORS['red'],
            arrowprops=dict(arrowstyle='->', color=COLORS['red'], lw=0.9),
            bbox=dict(boxstyle='round,pad=0.3', facecolor='white', edgecolor=COLORS['red'], alpha=0.9))
fig.tight_layout()
chart_drawdown = fig_to_b64(fig)
print("Chart 2 (drawdown) done.")


# Chart 3: Rolling 30-day Volatility
fig, ax = plt.subplots(figsize=(14, 4))
ax.fill_between(df.index, df['RollingVol30'], alpha=0.25, color=COLORS['gold'])
ax.plot(df.index, df['RollingVol30'], color=COLORS['gold'], linewidth=1.0)
ax.set_title('30-Day Rolling Annualized Volatility (%) — 2000–2026', fontsize=13, fontweight='bold',
             color=COLORS['primary'], pad=12)
ax.set_ylabel('Annualized Volatility (%)', fontsize=10)
ax.yaxis.set_major_formatter(mticker.FuncFormatter(lambda x, _: f'{x:.0f}%'))
ax.xaxis.set_major_formatter(mdates.DateFormatter('%Y'))
ax.xaxis.set_major_locator(mdates.YearLocator(2))
plt.setp(ax.xaxis.get_majorticklabels(), rotation=45, ha='right', fontsize=8)
# Mark vol spikes
high_vol = df['RollingVol30'].nlargest(5)
for dt, v in zip([df['RollingVol30'].idxmax()], [df['RollingVol30'].max()]):
    ax.annotate(f'{v:.0f}%\n({dt.strftime("%b %Y")})',
                xy=(dt, v), xytext=(20, -25), textcoords='offset points',
                fontsize=8, color=COLORS['gold'],
                arrowprops=dict(arrowstyle='->', color=COLORS['gold'], lw=0.8),
                bbox=dict(boxstyle='round,pad=0.2', facecolor='white', edgecolor=COLORS['gold'], alpha=0.9))
fig.tight_layout()
chart_vol = fig_to_b64(fig)
print("Chart 3 (volatility) done.")


# Chart 4: Annual Returns bar chart
fig, ax = plt.subplots(figsize=(14, 5))
valid_annual = annual_returns.dropna()
colors_bar = [COLORS['green'] if v >= 0 else COLORS['red'] for v in valid_annual.values]
bars = ax.bar(valid_annual.index.astype(str), valid_annual.values, color=colors_bar, alpha=0.85, width=0.7)
ax.axhline(0, color=COLORS['text'], linewidth=0.8, zorder=5)
ax.set_title('Nike (NKE) Annual Price Returns (%) — 2000–2026', fontsize=13, fontweight='bold',
             color=COLORS['primary'], pad=12)
ax.set_ylabel('Annual Return (%)', fontsize=10)
ax.yaxis.set_major_formatter(mticker.FuncFormatter(lambda x, _: f'{x:+.0f}%'))
plt.setp(ax.xaxis.get_majorticklabels(), rotation=60, ha='right', fontsize=8)
# Annotate best/worst
best_yr = valid_annual.idxmax()
worst_yr = valid_annual.idxmin()
for yr, mark in [(best_yr, '▲ Best'), (worst_yr, '▼ Worst')]:
    val = valid_annual[yr]
    color = COLORS['green'] if val > 0 else COLORS['red']
    ax.text(str(yr), val + (3 if val >= 0 else -5), f"{mark}\n{val:+.0f}%",
            ha='center', va='bottom' if val >= 0 else 'top',
            fontsize=7.5, color=color, fontweight='bold')
fig.tight_layout()
chart_annual = fig_to_b64(fig)
print("Chart 4 (annual returns) done.")


# Chart 5: Volume over time with price overlay
fig, ax1 = plt.subplots(figsize=(14, 5))
ax2 = ax1.twinx()
ax1.bar(monthly_vol.index, monthly_vol.values, color=COLORS['light_blue'], alpha=0.4, width=25, label='Avg Monthly Volume')
ax2.plot(monthly_close.index, monthly_close.values, color=COLORS['primary'], linewidth=1.5, label='Price')
ax1.set_title('Trading Volume vs. Price — Monthly (2000–2026)', fontsize=13, fontweight='bold',
              color=COLORS['primary'], pad=12)
ax1.set_ylabel('Avg Daily Volume (Millions)', fontsize=10, color=COLORS['light_blue'])
ax2.set_ylabel('Close Price (USD)', fontsize=10, color=COLORS['primary'])
ax1.yaxis.set_major_formatter(mticker.FuncFormatter(lambda x, _: f'{x:.0f}M'))
ax2.yaxis.set_major_formatter(mticker.FuncFormatter(lambda x, _: f'${x:.0f}'))
ax1.xaxis.set_major_formatter(mdates.DateFormatter('%Y'))
ax1.xaxis.set_major_locator(mdates.YearLocator(2))
plt.setp(ax1.xaxis.get_majorticklabels(), rotation=45, ha='right', fontsize=8)
lines1, labels1 = ax1.get_legend_handles_labels()
lines2, labels2 = ax2.get_legend_handles_labels()
ax1.legend(lines1 + lines2, labels1 + labels2, loc='upper left', fontsize=9)
fig.tight_layout()
chart_volume = fig_to_b64(fig)
print("Chart 5 (volume) done.")


# Chart 6: Decade comparison (2000s vs 2010s vs 2020s)
fig, axes = plt.subplots(1, 3, figsize=(14, 4), sharey=False)
decade_labels = ['2000–2009', '2010–2019', '2020–2026']
decade_ranges = [('2000', '2009'), ('2010', '2019'), ('2020', '2026')]
colors_dec = [COLORS['primary'], COLORS['light_blue'], COLORS['accent']]

for ax_d, (start, end), label, col in zip(axes, decade_ranges, decade_labels, colors_dec):
    mask = (df.index.year >= int(start)) & (df.index.year <= int(end))
    sub = df.loc[mask, 'Close']
    sub_monthly = sub.resample('ME').last()
    ax_d.fill_between(sub_monthly.index, sub_monthly.values, alpha=0.2, color=col)
    ax_d.plot(sub_monthly.index, sub_monthly.values, color=col, linewidth=1.8)
    start_p = sub.iloc[0]
    end_p = sub.iloc[-1]
    decade_ret = (end_p / start_p - 1) * 100
    ax_d.set_title(f'{label}\n{decade_ret:+.0f}% total', fontsize=10, fontweight='bold', color=col)
    ax_d.yaxis.set_major_formatter(mticker.FuncFormatter(lambda x, _: f'${x:.0f}'))
    ax_d.xaxis.set_major_formatter(mdates.DateFormatter("'%y"))
    ax_d.xaxis.set_major_locator(mdates.YearLocator(2))
    plt.setp(ax_d.xaxis.get_majorticklabels(), rotation=45, ha='right', fontsize=7.5)

fig.suptitle('Decade-Level Price Performance Comparison', fontsize=12, fontweight='bold',
             color=COLORS['primary'], y=1.02)
fig.tight_layout()
chart_decades = fig_to_b64(fig)
print("Chart 6 (decades) done.")


# Chart 7: Daily Price Range (volatility proxy)
daily_range_monthly = df['DailyRange'].resample('ME').mean()
fig, ax = plt.subplots(figsize=(14, 4))
ax.fill_between(daily_range_monthly.index, daily_range_monthly.values, alpha=0.3, color=COLORS['accent'])
ax.plot(daily_range_monthly.index, daily_range_monthly.values, color=COLORS['accent'], linewidth=1.2)
ax.set_title('Average Daily Price Range (High – Low) — Monthly Average, 2000–2026',
             fontsize=12, fontweight='bold', color=COLORS['primary'], pad=12)
ax.set_ylabel('Avg Daily Range (USD)', fontsize=10)
ax.yaxis.set_major_formatter(mticker.FuncFormatter(lambda x, _: f'${x:.2f}'))
ax.xaxis.set_major_formatter(mdates.DateFormatter('%Y'))
ax.xaxis.set_major_locator(mdates.YearLocator(2))
plt.setp(ax.xaxis.get_majorticklabels(), rotation=45, ha='right', fontsize=8)
fig.tight_layout()
chart_range = fig_to_b64(fig)
print("Chart 7 (daily range) done.")


# ── Build Annual Performance Table data ──────────────────────────────────────
annual_table_rows = []
for yr in sorted(valid_annual.index):
    ret = valid_annual[yr]
    vol = annual_vol.get(yr, np.nan)
    vol_m = annual_vol_volume.get(yr, np.nan)
    yr_data = df.loc[df.index.year == yr, 'Close']
    yr_open = yr_data.iloc[0] if len(yr_data) > 0 else np.nan
    yr_close = yr_data.iloc[-1] if len(yr_data) > 0 else np.nan
    annual_table_rows.append({
        'year': yr,
        'open': yr_open,
        'close': yr_close,
        'return': ret,
        'vol': vol,
        'avg_vol_m': vol_m
    })


# ── Save all chart data and KPIs to a dict for HTML generation ────────────────
report_data = {
    'first_date': first_date.strftime('%B %d, %Y'),
    'last_date': last_date.strftime('%B %d, %Y'),
    'years': f'{years:.1f}',
    'first_close': f'{first_close:.2f}',
    'last_close': f'{last_close:.2f}',
    'cumulative_return': f'{cumulative_return:.1f}',
    'cagr': f'{cagr:.2f}',
    'max_drawdown': f'{max_drawdown:.1f}',
    'ann_volatility': f'{ann_volatility:.1f}',
    'avg_volume': f'{avg_volume/1e6:.1f}',
    'ath': f'{ath:.2f}',
    'ath_date': ath_date.strftime('%B %d, %Y'),
    'atl': f'{atl:.2f}',
    'atl_date': atl_date.strftime('%B %d, %Y'),
    'max_drawdown_date': df['Drawdown'].idxmin().strftime('%B %d, %Y'),
    'best_year': str(best_yr),
    'best_year_ret': f'{valid_annual[best_yr]:+.1f}',
    'worst_year': str(worst_yr),
    'worst_year_ret': f'{valid_annual[worst_yr]:+.1f}',
    'annual_table_rows': annual_table_rows,
    'chart_price': chart_price,
    'chart_drawdown': chart_drawdown,
    'chart_vol': chart_vol,
    'chart_annual': chart_annual,
    'chart_volume': chart_volume,
    'chart_decades': chart_decades,
    'chart_range': chart_range,
}

# Decade summaries
for (start, end), label in zip(decade_ranges, decade_labels):
    mask = (df.index.year >= int(start)) & (df.index.year <= int(end))
    sub = df.loc[mask, 'Close']
    if len(sub) >= 2:
        ret = (sub.iloc[-1] / sub.iloc[0] - 1) * 100
        yrs = int(end) - int(start) + 1
        c = ((sub.iloc[-1] / sub.iloc[0]) ** (1/yrs) - 1) * 100
        report_data[f'dec_{start}_ret'] = f'{ret:.0f}'
