  .cover h1 {{
    font-size: 2.3rem;
    font-weight: 700;
    line-height: 1.25;
    margin-bottom: 12px;
    letter-spacing: -0.01em;
  }}
  .cover-sub {{
    font-size: 1.05rem;
    opacity: 0.82;
    max-width: 640px;
    margin-bottom: 28px;
  }}
  .cover-meta {{
    display: flex;
    gap: 28px;
    font-size: 12.5px;
    opacity: 0.7;
    flex-wrap: wrap;
  }}
  .cover-meta span {{ display: flex; align-items: center; gap: 5px; }}

  /* ── KPI Dashboard ── */
  .kpi-grid {{
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(190px, 1fr));
    gap: 16px;
    margin-bottom: 36px;
  }}
  .kpi-card {{
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: var(--radius);
    padding: 22px 20px 18px;
    box-shadow: var(--shadow);
    position: relative;
    overflow: hidden;
  }}
  .kpi-card::before {{
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 4px;
    border-radius: var(--radius) var(--radius) 0 0;
  }}
  .kpi-card.blue::before   {{ background: var(--primary); }}
  .kpi-card.green::before  {{ background: var(--green); }}
  .kpi-card.red::before    {{ background: var(--red); }}
  .kpi-card.gold::before   {{ background: var(--gold); }}
  .kpi-card.accent::before {{ background: var(--accent); }}
  .kpi-label {{
    font-size: 11.5px;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.07em;
    color: var(--text-muted);
    margin-bottom: 8px;
  }}
  .kpi-value {{
    font-size: 2rem;
    font-weight: 700;
    line-height: 1.1;
    margin-bottom: 4px;
  }}
  .kpi-value.green {{ color: var(--green); }}
  .kpi-value.red   {{ color: var(--red); }}
  .kpi-value.blue  {{ color: var(--primary); }}
  .kpi-value.gold  {{ color: var(--gold); }}
  .kpi-sub {{
    font-size: 12px;
    color: var(--text-muted);
  }}

  /* ── Section Containers ── */
  .section {{
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: var(--radius);
    padding: 32px 36px;
    margin-bottom: 28px;
    box-shadow: var(--shadow);
  }}
  .section-header {{
    display: flex;
    align-items: flex-start;
    gap: 14px;
    margin-bottom: 20px;
    padding-bottom: 16px;
    border-bottom: 2px solid var(--border);
  }}
  .section-num {{
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 32px;
    height: 32px;
    background: var(--primary);
    color: white;
    font-size: 13px;
    font-weight: 700;
    border-radius: 6px;
    flex-shrink: 0;
    margin-top: 2px;
  }}
  .section-title {{
    font-size: 1.25rem;
    font-weight: 700;
    color: var(--primary);
  }}
  .section-sub {{
    font-size: 13px;
    color: var(--text-muted);
    margin-top: 3px;
  }}

  /* ── Executive Summary ── */
  .exec-summary p {{
    font-size: 15px;
    line-height: 1.75;
    color: var(--text);
    margin-bottom: 14px;
  }}
  .callout {{
    background: #EBF2FA;
    border-left: 4px solid var(--primary);
    border-radius: 0 6px 6px 0;
    padding: 14px 18px;
    margin: 18px 0;
    font-size: 14.5px;
    color: var(--primary);
  }}
  .callout.warn {{
    background: #FFF3E0;
    border-color: var(--accent);
    color: #7B3200;
  }}
  .callout.success {{
    background: #E8F5E9;
    border-color: var(--green);
    color: #1B5E20;
  }}

  /* ── Charts ── */
  .chart-wrap {{
    margin: 22px 0;
    text-align: center;
  }}
  .chart-wrap img {{
    max-width: 100%;
    border-radius: 8px;
    border: 1px solid var(--border);
  }}
  .chart-caption {{
    font-size: 12.5px;
    color: var(--text-muted);
    margin-top: 8px;
    font-style: italic;
  }}

  /* ── Phase Table ── */
  .phase-grid {{
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 14px;
    margin: 18px 0;
  }}
  .phase-card {{
    background: var(--bg);
    border: 1px solid var(--border);
    border-radius: 8px;
    padding: 16px;
  }}
  .phase-card .phase-name {{
    font-size: 11.5px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    color: var(--text-muted);
    margin-bottom: 6px;
  }}
  .phase-card .phase-period {{
    font-size: 14px;
    font-weight: 600;
    color: var(--primary);
    margin-bottom: 4px;
  }}
  .phase-card .phase-desc {{
    font-size: 13px;
    color: var(--text);
    line-height: 1.55;
  }}
  .phase-card .phase-ret {{
    font-size: 17px;
    font-weight: 700;
    margin-top: 8px;
  }}
  .pos {{ color: var(--green); }}
  .neg {{ color: var(--red); }}

  /* ── Annual Table ── */
  .data-table {{
    width: 100%;
    border-collapse: collapse;
    font-size: 13.5px;
    margin: 18px 0;
  }}
  .data-table th {{
    background: var(--primary);
    color: white;
    padding: 10px 12px;
    text-align: right;
    font-size: 11.5px;
    font-weight: 600;
    letter-spacing: 0.04em;
    text-transform: uppercase;
  }}
  .data-table th:first-child {{ text-align: left; border-radius: 6px 0 0 0; }}
  .data-table th:last-child  {{ border-radius: 0 6px 0 0; }}
  .data-table td {{
    padding: 8px 12px;
    text-align: right;
    border-bottom: 1px solid var(--border);
    vertical-align: middle;
  }}
  .data-table td.year-col {{ text-align: left; font-weight: 600; color: var(--primary); }}
  .data-table tr:hover td {{ background: #F0F4FA; }}
  .data-table td.pos {{ color: var(--green); font-weight: 600; }}
  .data-table td.neg {{ color: var(--red); font-weight: 600; }}

  /* ── Insight Bullets ── */
  .insights {{ list-style: none; padding: 0; }}
  .insights li {{
    padding: 9px 12px 9px 36px;
    position: relative;
    border-radius: 6px;
    margin-bottom: 6px;
    background: var(--bg);
    font-size: 14.5px;
    line-height: 1.6;
  }}
  .insights li::before {{
    content: '→';
    position: absolute;
    left: 12px;
    color: var(--primary);
    font-weight: 700;
  }}
  .insights li.green-bg {{ background: #E8F5E9; }}
  .insights li.red-bg   {{ background: #FFEBEE; }}
  .insights li.blue-bg  {{ background: #E3EEF8; }}

  /* ── Decade Summary ── */
  .decade-row {{
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 16px;
    margin: 18px 0;
  }}
  .decade-card {{
    border-radius: 8px;
    padding: 18px;
    background: var(--bg);
    border: 1px solid var(--border);
  }}
  .decade-card h4 {{
    font-size: 13px;
    font-weight: 700;
    color: var(--primary);
    margin-bottom: 8px;
    text-transform: uppercase;
    letter-spacing: 0.05em;
  }}
  .decade-stat {{ font-size: 13px; margin-bottom: 4px; color: var(--text); }}
  .decade-stat span {{ font-weight: 600; }}

  /* ── Footer ── */
  .report-footer {{
    text-align: center;
    padding: 28px 0 0;
    font-size: 12px;
    color: var(--text-muted);
    border-top: 1px solid var(--border);
    margin-top: 40px;
  }}
  .report-footer strong {{ color: var(--text); }}

  /* ── Responsive ── */
  @media (max-width: 680px) {{
    .cover {{ padding: 32px 24px 28px; margin: 0 -24px 24px; }}
    .cover h1 {{ font-size: 1.65rem; }}
    .kpi-grid {{ grid-template-columns: repeat(2, 1fr); }}
    .section {{ padding: 20px 18px; }}
    .decade-row {{ grid-template-columns: 1fr; }}
  }}
  @media print {{
    body {{ background: white; }}
    .section {{ box-shadow: none; border: 1px solid #ccc; }}
    .cover {{ -webkit-print-color-adjust: exact; print-color-adjust: exact; }}
  }}
</style>
</head>
<body>
<div class="page">

  <!-- ══════════════════════════════════════════════════════════════════════ -->
  <!--  COVER                                                                  -->
  <!-- ══════════════════════════════════════════════════════════════════════ -->
  <header class="cover">
    <div class="cover-logo">
      <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
        <polyline points="22 12 18 12 15 21 9 3 6 12 2 12"></polyline>
      </svg>
      Equity Research — Historical Performance Analysis
    </div>
    <div class="cover-ticker">NYSE: NKE</div>
    <h1>Nike Inc. (NKE)<br>Historical Stock Performance<br>Analysis 2000–2026</h1>
    <p class="cover-sub">A comprehensive 26-year examination of Nike's equity price trajectory, risk metrics, trading volume patterns, and long-term return profile — designed to inform capital allocation decisions.</p>
    <div class="cover-meta">
      <span>
        <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><rect x="3" y="4" width="18" height="18" rx="2"/><line x1="16" y1="2" x2="16" y2="6"/><line x1="8" y1="2" x2="8" y2="6"/><line x1="3" y1="10" x2="21" y2="10"/></svg>
        Data Period: {report_data['first_date']} — {report_data['last_date']}
      </span>
      <span>
        <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg>
        Generated: April 21, 2026
      </span>
      <span>
        <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><path d="M21 16V8a2 2 0 0 0-1-1.73l-7-4a2 2 0 0 0-2 0l-7 4A2 2 0 0 0 3 8v8a2 2 0 0 0 1 1.73l7 4a2 2 0 0 0 2 0l7-4A2 2 0 0 0 21 16z"/></svg>
        6,559 Trading Days Analyzed
      </span>
      <span>
        <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><line x1="18" y1="20" x2="18" y2="10"/><line x1="12" y1="20" x2="12" y2="4"/><line x1="6" y1="20" x2="6" y2="14"/></svg>
        Adjusted Prices — Splits & Dividends
      </span>
    </div>
  </header>


  <!-- ══════════════════════════════════════════════════════════════════════ -->
  <!--  KPI DASHBOARD                                                         -->
  <!-- ══════════════════════════════════════════════════════════════════════ -->
  <div class="kpi-grid">
    <div class="kpi-card green">
      <div class="kpi-label">Cumulative Return</div>
      <div class="kpi-value green">+{report_data['cumulative_return']}%</div>
      <div class="kpi-sub">${report_data['first_close']} → ${report_data['last_close']} per share</div>
    </div>
    <div class="kpi-card blue">
      <div class="kpi-label">CAGR (26 Years)</div>
      <div class="kpi-value blue">{report_data['cagr']}%</div>
      <div class="kpi-sub">Compound annual growth rate</div>
    </div>
    <div class="kpi-card red">
      <div class="kpi-label">Maximum Drawdown</div>
      <div class="kpi-value red">{report_data['max_drawdown']}%</div>
      <div class="kpi-sub">Deepest peak-to-trough decline</div>
    </div>
    <div class="kpi-card gold">
      <div class="kpi-label">Annualized Volatility</div>
      <div class="kpi-value gold">{report_data['ann_volatility']}%</div>
      <div class="kpi-sub">Std dev of daily returns × √252</div>
    </div>
    <div class="kpi-card accent">
      <div class="kpi-label">Avg Daily Volume</div>
      <div class="kpi-value" style="font-size:1.7rem;color:var(--accent)">{report_data['avg_volume']}M</div>
      <div class="kpi-sub">Shares per trading day (mean)</div>
    </div>
    <div class="kpi-card blue">
      <div class="kpi-label">All-Time High</div>
      <div class="kpi-value" style="font-size:1.7rem;color:var(--primary-light)">${report_data['ath']}</div>
      <div class="kpi-sub">{report_data['ath_date']}</div>
    </div>
  </div>


  <!-- ══════════════════════════════════════════════════════════════════════ -->
  <!--  SECTION 1: EXECUTIVE SUMMARY                                          -->
  <!-- ══════════════════════════════════════════════════════════════════════ -->
  <div class="section exec-summary">
    <div class="section-header">
      <span class="section-num">01</span>
      <div>
        <div class="section-title">Executive Summary</div>
        <div class="section-sub">26-Year performance overview and key milestones</div>
      </div>
    </div>

    <p>Nike Inc. (NYSE: NKE) has been one of the defining compounders of the modern equity era. Over the 26-year period from <strong>January 3, 2000 to January 30, 2026</strong>, the adjusted closing price appreciated from <strong>${report_data['first_close']}</strong> to <strong>${report_data['last_close']}</strong> — a cumulative gain of <strong>+{report_data['cumulative_return']}%</strong>, equivalent to a <strong>{report_data['cagr']}% compound annual growth rate (CAGR)</strong>. This significantly outpaced the long-run average equity market return of approximately 8–10% annually.</p>

    <div class="callout success">
      <strong>Key Finding:</strong> A $10,000 investment in NKE on January 3, 2000 would have grown to approximately <strong>${10000 * (1 + float(report_data['cumulative_return'])/100):,.0f}</strong> by January 30, 2026, excluding dividends and transaction costs.
    </div>

    <p>Nike's journey was not without turbulence. The stock endured four distinct major drawdown episodes — the dot-com era correction (2000–2003), the Global Financial Crisis (2007–2009), a mid-cycle valuation reset (2021–2022), and ongoing macro pressures (2023–2026). The deepest decline was <strong>{report_data['max_drawdown']}%</strong>, demonstrating that long-horizon holding required meaningful tolerance for interim capital loss.</p>

    <p>From a risk-adjusted standpoint, Nike's <strong>{report_data['ann_volatility']}% annualized volatility</strong> over the full period is typical for a large-cap consumer discretionary stock — higher than pure staples or utilities, but meaningfully lower than high-growth technology peers. The stock's all-time high of <strong>${report_data['ath']}</strong> was reached on <strong>{report_data['ath_date']}</strong>.</p>

    <div class="callout">
      <strong>Investment Lens:</strong> Nike's equity profile is that of a long-term compounder with cyclical drawdown risk. Investors who held through all major corrections captured the full 26-year appreciation; those who timed exits around crises likely missed significant subsequent rebounds.
    </div>
  </div>


  <!-- ══════════════════════════════════════════════════════════════════════ -->
  <!--  SECTION 2: LONG-TERM PRICE TREND ANALYSIS                            -->
  <!-- ══════════════════════════════════════════════════════════════════════ -->
  <div class="section">
    <div class="section-header">
      <span class="section-num">02</span>
      <div>
        <div class="section-title">Long-Term Price Trend Analysis</div>
        <div class="section-sub">Structural bull/bear phases, all-time highs and lows, and inflection points</div>
      </div>
    </div>

    <div class="chart-wrap">
      <img src="data:image/png;base64,{report_data['chart_price']}" alt="Nike Long-Term Price Trend 2000-2026">
      <div class="chart-caption">Figure 1 — NKE monthly closing price (adjusted), 2000–2026. Shaded red zones indicate major drawdown periods. Prices reflect retroactive adjustment for stock splits and dividends.</div>
    </div>

    <h3 style="font-size:1rem;font-weight:700;color:var(--primary);margin:24px 0 14px;">Structural Market Phases</h3>
    <div class="phase-grid">
      <div class="phase-card">
        <div class="phase-name">Phase I — Consolidation</div>
        <div class="phase-period">2000–2003</div>
        <div class="phase-desc">Post-dot-com era. Nike traded in a compressed range while broader markets declined. Relative resilience vs. tech-heavy indices.</div>
        <div class="phase-ret neg">Flat to modest decline</div>
      </div>
      <div class="phase-card">
        <div class="phase-name">Phase II — Initial Bull Run</div>
        <div class="phase-period">2003–2007</div>
        <div class="phase-desc">Strong consumer spending environment. Nike's international expansion and product innovation drove consistent price appreciation.</div>
        <div class="phase-ret pos">~+200% gain</div>
      </div>
      <div class="phase-card">
        <div class="phase-name">Phase III — GFC Drawdown</div>
        <div class="phase-period">2007–2009</div>
        <div class="phase-desc">Global financial crisis caused a sharp but recoverable drawdown. Nike's brand resilience limited permanent impairment.</div>
        <div class="phase-ret neg">~–54% peak-to-trough</div>
      </div>
      <div class="phase-card">
        <div class="phase-name">Phase IV — Mega Bull Run</div>
        <div class="phase-period">2009–2021</div>
        <div class="phase-desc">The dominant phase of Nike's 26-year history. 12 consecutive years of structural appreciation driven by DTC pivot, digital growth, and brand premiumization.</div>
        <div class="phase-ret pos">~+1,500%+ appreciation</div>
      </div>
      <div class="phase-card">
        <div class="phase-name">Phase V — COVID Shock</div>
        <div class="phase-period">Feb–Apr 2020</div>
        <div class="phase-desc">Sharp V-shaped correction. The fastest recovery in NKE's history — the stock reclaimed pre-crash highs within months, aided by DTC and digital tailwinds.</div>
        <div class="phase-ret neg">–32% then swift recovery</div>
      </div>
      <div class="phase-card">
        <div class="phase-name">Phase VI — Post-ATH Reset</div>
        <div class="phase-period">2021–2026</div>
        <div class="phase-desc">After reaching all-time highs near $179 in late 2021, NKE entered a prolonged valuation reset amid supply chain disruption, margin pressure, and shifting consumer dynamics.</div>
        <div class="phase-ret neg">Structural retracement</div>
      </div>
    </div>

    <div class="callout">
      <strong>All-Time High:</strong> ${report_data['ath']} on {report_data['ath_date']} &nbsp;|&nbsp; <strong>All-Time Low (adjusted):</strong> ${report_data['atl']} on {report_data['atl_date']}
    </div>
  </div>


  <!-- ══════════════════════════════════════════════════════════════════════ -->
  <!--  SECTION 3: VOLATILITY & RISK ASSESSMENT                               -->
  <!-- ══════════════════════════════════════════════════════════════════════ -->
  <div class="section">
    <div class="section-header">
      <span class="section-num">03</span>
      <div>
        <div class="section-title">Volatility and Risk Assessment</div>
        <div class="section-sub">Drawdown analysis, rolling volatility, and daily price range</div>
      </div>
    </div>

    <h3 style="font-size:0.95rem;font-weight:700;color:var(--primary);margin:0 0 12px;">Peak-to-Trough Drawdown Profile</h3>
    <div class="chart-wrap">
      <img src="data:image/png;base64,{report_data['chart_drawdown']}" alt="Nike Drawdown Chart">
      <div class="chart-caption">Figure 2 — Rolling peak-to-trough drawdown (%) based on daily closing prices. The deepest drawdown of {report_data['max_drawdown']}% occurred around {report_data['max_drawdown_date']}.</div>
    </div>

    <h3 style="font-size:0.95rem;font-weight:700;color:var(--primary);margin:22px 0 12px;">30-Day Rolling Annualized Volatility</h3>
    <div class="chart-wrap">
      <img src="data:image/png;base64,{report_data['chart_vol']}" alt="Nike Rolling Volatility">
      <div class="chart-caption">Figure 3 — 30-day rolling annualized volatility (%), capturing how risk evolved across different market regimes.</div>
    </div>

    <h3 style="font-size:0.95rem;font-weight:700;color:var(--primary);margin:22px 0 12px;">Daily Intraday Price Range</h3>
    <div class="chart-wrap">
      <img src="data:image/png;base64,{report_data['chart_range']}" alt="Nike Daily Price Range">
      <div class="chart-caption">Figure 4 — Monthly average of the daily High–Low spread (USD), a direct measure of intraday price instability.</div>
    </div>

    <ul class="insights" style="margin-top:18px;">
      <li class="red-bg"><strong>Maximum Drawdown of {report_data['max_drawdown']}%</strong> represents the worst outcome for an investor who bought near a peak and held through the trough — a meaningful risk for concentration or margin positions.</li>
      <li class="blue-bg">Volatility spikes align closely with macro crises: the 2008–2009 GFC and the March 2020 COVID shock produced the highest realized volatility readings of the entire period.</li>
      <li class="green-bg">The 2012–2019 "calm bull" period shows notably compressed volatility, with the 30-day rolling figure often below 20% — an unusually benign environment that rewarded long holders.</li>
      <li>Daily price ranges (High–Low) expand proportionally with price level post-2010, but the range as a <em>percentage</em> of price remained relatively stable, confirming that absolute dollar volatility grew with the stock's appreciation.</li>
    </ul>
  </div>


  <!-- ══════════════════════════════════════════════════════════════════════ -->
  <!--  SECTION 4: TRADING VOLUME PATTERNS                                    -->
  <!-- ══════════════════════════════════════════════════════════════════════ -->
  <div class="section">
    <div class="section-header">
      <span class="section-num">04</span>
      <div>
        <div class="section-title">Trading Volume Patterns</div>
        <div class="section-sub">Volume trends, spikes, and correlation with price behavior</div>
      </div>
    </div>

    <div class="chart-wrap">
      <img src="data:image/png;base64,{report_data['chart_volume']}" alt="Nike Volume vs Price">
      <div class="chart-caption">Figure 5 — Monthly average daily trading volume (bars, left axis) overlaid with monthly closing price (line, right axis). Volume and price dynamics reveal key market sentiment shifts.</div>
    </div>

    <ul class="insights" style="margin-top:18px;">
      <li class="blue-bg"><strong>Peak volume era: 2009–2013.</strong> The post-GFC recovery coincided with elevated trading activity — institutional accumulation and retail re-entry drove both volume and price higher simultaneously.</li>
      <li>Volume structurally declined through the 2015–2019 bull phase as the stock's trend became consensus — fewer sellers meant less two-sided volume, but the price continued appreciating.</li>
      <li class="red-bg"><strong>March 2020 COVID crash</strong> produced a sharp volume spike. The combination of forced selling and opportunistic buying generated some of the highest single-day volumes in the dataset's history.</li>
      <li>Post-2021 volume patterns show sustained activity above the 2015–2019 lows, consistent with increased price-level uncertainty and active repositioning as the stock gave back multi-year gains.</li>
      <li>Average daily volume over the full period: <strong>{report_data['avg_volume']}M shares</strong>. Nike remains a highly liquid large-cap, ensuring minimal market impact for institutional-scale transactions.</li>
    </ul>
  </div>


  <!-- ══════════════════════════════════════════════════════════════════════ -->
  <!--  SECTION 5: ANNUAL & DECADE-LEVEL PERFORMANCE                          -->
  <!-- ══════════════════════════════════════════════════════════════════════ -->
  <div class="section">
    <div class="section-header">
      <span class="section-num">05</span>
      <div>
        <div class="section-title">Annual and Decade-Level Performance Breakdown</div>
        <div class="section-sub">Year-over-year returns, best/worst years, and decade compounding</div>
      </div>
    </div>

